// Generated by scripts/fleet/sync_agents.py: edit the generator, then run `make agents`.
// The Rekkit guards before each tool call, as agy and Claude Code run them (scripts/fleet/hook.sh):
// no push, sign, release, submodule change, force or recursive delete; nothing under horizon/; no
// code under mods/<id>/content/; no whole decompiled class; no folder sweeps or toolchain reads by a
// role subagent; the subagent token budget. And the tracker context (its resume page, while a mod is in
// progress, its resume page) in the main session's system prompt, as agy and Claude Code get it at
// session start, so no agent loads it itself; again when a session is compacted.
import { spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";

// Subagents run only under Claude Code, agy and grok. opencode runs a local model (Ollama, LM Studio,
// llama.cpp) most of the time, so opencode's subagent tool is blocked for every model unless the
// operator sets REKKIT_ALLOW_SUBAGENTS=1 in a session on a cloud model. ("task" is the older name.)
const SUBAGENT_TOOLS = new Set(["subagent", "task"]);
const CHECKS = { bash: "shell", edit: "paths", write: "paths", patch: "paths", read: "read", grep: "read", glob: "read", list: "read", subagent: "spawn", task: "spawn" };
const HOOK = fileURLToPath(new URL("../../scripts/fleet/hook.sh", import.meta.url));

const guard = (check, payload) =>
  spawnSync("bash", [HOOK, check, "claude"], { input: JSON.stringify(payload ?? {}), encoding: "utf8" });
const prime = () => {
  const r = guard("prime");
  return r.status === 0 ? (r.stdout || "").trim() : "";
};
// One text per session, so the system prompt stays the same from turn to turn (and stays cached).
const primed = new Map();

// opencode (plugin API 2.x) loads a module's default export: an id and a setup function that gets the
// context and registers hooks on it. Hooks: ctx.tool.hook (before a tool call), ctx.session.hook
// ("context" before each model request, "compaction" when a session is compacted).
export default {
  id: "rekkit-guard",
  async setup(ctx) {
    // A role subagent's session has a parent: it gets no tracker context (its brief is fleet-task's).
    const isSubagent = async (sessionID) => {
      try {
        return Boolean((await ctx.session.get({ sessionID }))?.parentID);
      } catch {
        return false;
      }
    };
    // Throwing in a before-hook blocks the tool call and returns the message to the model.
    await ctx.tool.hook("execute.before", async (event) => {
      if (SUBAGENT_TOOLS.has(event.tool) && process.env.REKKIT_ALLOW_SUBAGENTS !== "1")
        throw new Error("Subagents are off on opencode: do the role yourself, one ticket at a time (AGENTS.md).");
      const check = CHECKS[event.tool];
      if (!check) return;
      const r = guard(check, { session_id: event.sessionID ?? "", tool_name: event.tool, tool_input: event.input ?? {} });
      if (r.status === 2) throw new Error((r.stderr || "Blocked by the Rekkit fleet guard").trim());
    });
    // The context hook runs before every model request; `system` is the system prompt's text list.
    await ctx.session.hook("context", async (x) => {
      const id = x?.sessionID;
      if (!id || !x.system) return;
      if (!primed.has(id)) primed.set(id, (await isSubagent(id)) ? "" : prime());
      const text = primed.get(id);
      if (text) x.system.push({ type: "text", text });
    });
    // After compaction the next request re-reads the tracker context.
    await ctx.session.hook("compaction", async (x) => {
      if (x?.sessionID) primed.delete(x.sessionID);
    });
  },
};
